const claimedReplay = (result: SendblueReplayClaimResult) =>
  Match.value(result).pipe(
    Match.when({ status: "claimed" }, ({ claim }) => Effect.succeed(claim)),
    Match.orElse(() => Effect.die("Expected Sendblue replay claim."))
